interface DocState { readonly text: string; readonly caret: number }
type Action = { kind: 'text'; value: string } | { kind: 'caret'; value: number };

class Editor {
  #state: DocState = { text: '', caret: 0 };
  #history: DocState[] = [];                       // caretaker
  save() { this.#history.push(structuredClone(this.#state)); }
  apply(action: Action) {
    this.save();                                   // snapshot before the change
    this.#state = structuredClone({ ...this.#state, ...action });
  }
  undo() { this.#state = this.#history.pop() ?? this.#state; }
}
